function extractClipboardFiles(clipboardData){
    const files = [];
    if(!clipboardData) return files;
    if(clipboardData.items && clipboardData.items.length){
        for(const item of clipboardData.items){
            if(item.kind === 'file' || (item.type && (item.type.startsWith('image/') || item.type.startsWith('video/') || item.type.startsWith('audio/')))){
                const f = item.getAsFile();
                if(f) {
                    if(!f.name || f.name === 'image.png' || f.name === 'blob'){
                        const ext = (f.type && f.type.split('/')[1]) || 'png';
                        const fileWithName = new File([f], `paste-${Date.now()}.${ext}`, {type: f.type || 'image/png'});
                        files.push(fileWithName);
                    } else {
                        files.push(f);
                    }
                }
            }
        }
    }
    if(!files.length && clipboardData.files && clipboardData.files.length){
        for(const f of clipboardData.files){
            if(f) files.push(f);
        }
    }
    return files.filter(isSupportedUploadFile);
}
window.addEventListener('paste', async e => {
    // 优先从剪贴板提取图片/媒体文件
    let files = extractClipboardFiles(e.clipboardData);
    if(files.length){
        e.preventDefault();
        lastImagePasteAt = Date.now();
        const sel = selectedNode();
        const isBlankImageNode = isSmartImageNode(sel) && (!sel.images || sel.images.length === 0);
        const isGroup = isSmartGroupNode(sel);
        const point = lastMouseWorld || viewportCenter();
        if(isGroup){
            await handleFiles(files, sel.id, {point});
        } else if(isBlankImageNode){
            await handleFiles(files, sel.id);
        } else {
            await handleFiles(files, '', {point, forceNew:true, createGroup:false});
        }
        return;
    }
    // 素材库管理页「复制到画布」过来的素材：Ctrl+V 批量粘贴成图片节点
    if(!isEditableTarget(e.target) && pasteAssetsFromInbox()){
        e.preventDefault();
        return;
    }
    if(nodeClipboard?.nodes?.length && !isEditableTarget(e.target)){
        e.preventDefault();
        pasteNodes();
        return;
    }
    // 非编辑输入区且剪贴板文本为本地图片路径或远程图片URL时，自动创建上传节点导入
    if(!isEditableTarget(e.target) && e.clipboardData){
        const text = String(e.clipboardData.getData('text/plain') || '').trim();
        if(text){
            const point = lastMouseWorld || viewportCenter();
            const sel = selectedNode();
            const isBlank = isSmartImageNode(sel) && (!sel.images || sel.images.length === 0);
            const isGroup = isSmartGroupNode(sel);
            const targetId = (isGroup || isBlank) ? sel.id : '';
            if(isLocalSmartImageDropValue(text)){
                e.preventDefault();
                await handleSmartImageDropPayload({type:'localPaths', localPaths:[text]}, targetId, {point, forceNew:!targetId, createGroup:false});
                return;
            }
            if(isRemoteSmartImageDropValue(text) && /\.(png|jpe?g|webp|gif|bmp|svg|avif|heic|ico|tiff|mp4|webm|mov)(\?|$)/i.test(text)){
                e.preventDefault();
                await handleSmartImageDropPayload({type:'url', url:text}, targetId, {point, forceNew:!targetId, createGroup:false});
                return;
            }
        }
    }
});
window.addEventListener('keydown', e => {
    const key = String(e.key || '').toLowerCase();
    if((e.code === 'Space' || e.key === ' ') && !e.ctrlKey && !e.metaKey && !e.altKey && !isEditableTarget(e.target)){
        const active = selectedNode();
        if(active?.type === 'smart-minimax'){
            const nodeEl = [...(world?.querySelectorAll?.('.image-node') || [])].find(item => item.dataset.id === active.id);
            const playBtn = nodeEl?.querySelector?.('[data-minimax-play-timeline]');
            if(playBtn){
                e.preventDefault();
                playBtn.click();
                return;
            }
        }
    }
    if(key === 'r' && !isEditableTarget(e.target)) isRKeyDown = true;
    if(imageEditModal.classList.contains('open') && imageEditMode === 'preview' && !isEditableTarget(e.target)){
        if(e.key === 'ArrowLeft' || e.key === 'ArrowRight'){
            e.preventDefault();
            if(!seekPreviewVideoFrames(e.key === 'ArrowLeft' ? -1 : 1)){
                navigatePreviewImage(e.key === 'ArrowLeft' ? -1 : 1);
            }
            return;
        }
    }
    if(!e.ctrlKey && !e.metaKey && !e.altKey && !isEditableTarget(e.target)){
        if(key === 'z'){
            if(e.repeat) return;
            e.preventDefault();
            toggleZoomPreview();
            return;
        }
        if(key === 'a'){
            if(e.repeat) return;
            e.preventDefault();
            toggleAssetLibrary();
            return;
        }
    }
    if((e.ctrlKey || e.metaKey) && key === 'c' && !isEditableTarget(e.target)){
        const selectionText = window.getSelection?.().toString() || '';
        if(selectionText) return;
        e.preventDefault();
        copySelectedNodes();
        return;
    }
    if((e.ctrlKey || e.metaKey) && key === 'v' && !isEditableTarget(e.target) && nodeClipboard?.nodes?.length){
        const requestedAt = Date.now();
        setTimeout(() => {
            if(lastImagePasteAt >= requestedAt) return;
            if(lastNodePasteAt >= requestedAt) return;
            pasteNodes();
        }, 90);
    }
    if(e.key === 'Escape' && imageEditModal.classList.contains('open')){
        closeImageEditor();
        return;
    }
    if((e.ctrlKey || e.metaKey) && key === 'z' && !isEditableTarget(e.target)){
        e.preventDefault();
        performUndo();
        return;
    }
    if((e.key === 'Delete' || e.key === 'Backspace') && (selectedId || selectedIds.length) && !isEditableTarget(e.target)){
        e.preventDefault();
        const ids = selectedIds.length ? selectedIds.slice() : [selectedId];
        pushUndo();
        ids.forEach(id => { undoSuppressed = true; deleteNode(id); undoSuppressed = false; });
        render();
        scheduleSave();
    }
    if((e.ctrlKey || e.metaKey) && e.shiftKey && key === 'g' && !isEditableTarget(e.target)){
        e.preventDefault();
        const ids = selectedIds.length ? selectedIds.slice() : (selectedId ? [selectedId] : []);
        const ok = ids.map(id => ungroupNode(id)).some(Boolean);
        if(ok) return;
    }
    if((e.ctrlKey || e.metaKey) && key === 'g' && !e.shiftKey && !isEditableTarget(e.target)){
        e.preventDefault();
        groupSelectedNodes();
    }
});
window.addEventListener('keyup', e => {
    if(String(e.key || '').toLowerCase() === 'r') isRKeyDown = false;
});
window.addEventListener('blur', () => {
    isRKeyDown = false;
});
