        if(skippedCount > 0) progressParts.push(`${skippedCount}已跳过`);
        const progress = progressParts.length ? ` · ${progressParts.join(' · ')}` : '';
        // 构建 prompt 列表（已确认/已跳过的折叠，当前展开，pending 灰色）
